<?php
declare(strict_types=1);

function pbSchema(PDO $db): void {
    $db->exec("CREATE TABLE IF NOT EXISTS private_business_numbers (suffix INTEGER PRIMARY KEY, number VARCHAR(8) NOT NULL UNIQUE, year INTEGER NOT NULL, kind VARCHAR(20) NOT NULL, source_key VARCHAR(190) NOT NULL UNIQUE, created_at VARCHAR(30) NOT NULL)");
    $db->exec("CREATE TABLE IF NOT EXISTS private_business_records (id VARCHAR(36) PRIMARY KEY, profile VARCHAR(30) NOT NULL, number VARCHAR(8) NOT NULL UNIQUE, kind VARCHAR(20) NOT NULL, parent_id VARCHAR(36) NULL, request_key VARCHAR(36) NOT NULL UNIQUE, folder_id VARCHAR(190) NULL, payload_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, status VARCHAR(30) NOT NULL DEFAULT 'draft', created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL)");
    $db->exec("CREATE TABLE IF NOT EXISTS private_business_documents (record_id VARCHAR(36) NOT NULL, revision INTEGER NOT NULL, kind VARCHAR(30) NOT NULL, item_id VARCHAR(190) NOT NULL, filename VARCHAR(240) NOT NULL, sha256 VARCHAR(64) NOT NULL, PRIMARY KEY(record_id,revision,kind))");
    $db->exec("CREATE TABLE IF NOT EXISTS private_business_events (id VARCHAR(36) PRIMARY KEY, record_id VARCHAR(36) NOT NULL, event VARCHAR(30) NOT NULL, detail_json TEXT NOT NULL, created_at VARCHAR(30) NOT NULL)");
    $db->exec("CREATE TABLE IF NOT EXISTS private_business_dispatches (id VARCHAR(36) PRIMARY KEY, record_id VARCHAR(36) NOT NULL, profile VARCHAR(30) NOT NULL, revision INTEGER NOT NULL, state VARCHAR(30) NOT NULL, detail_json TEXT NOT NULL, created_at VARCHAR(30) NOT NULL)");
}
function pbUuid(): string {$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-a'.substr($h,17,3).'-'.substr($h,20);}
function pbNow(): string {return gmdate('Y-m-d H:i:s');}
function pbNumber(PDO $db,string $kind,string $source,?int $year=null,?callable $random=null): string {
    $q=$db->prepare('SELECT number FROM private_business_numbers WHERE source_key=?');$q->execute([$source]);if($n=$q->fetchColumn())return (string)$n;
    $year??=(int)(new DateTimeImmutable('now',new DateTimeZone('Europe/Berlin')))->format('Y');
    for($i=0;$i<200;$i++){$suffix=$random?$random():random_int(10000,99999);$number=sprintf('%02d-%05d',$year%100,$suffix);try{$q=$db->prepare('INSERT INTO private_business_numbers(suffix,number,year,kind,source_key,created_at) VALUES(?,?,?,?,?,?)');$q->execute([$suffix,$number,$year,$kind,$source,pbNow()]);return $number;}catch(PDOException $e){if(!in_array((string)$e->getCode(),['23000','23505','19'],true))throw $e;$q=$db->prepare('SELECT number FROM private_business_numbers WHERE source_key=?');$q->execute([$source]);if($n=$q->fetchColumn())return(string)$n;}}
    throw new RuntimeException('Keine freie Nummer gefunden. Bitte erneut speichern.');
}
function pbNativeCaseNumber(PDO $db,string $folderId,?int $year=null): string {$q=$db->prepare('SELECT number FROM private_business_numbers WHERE source_key=?');$q->execute(['folder:'.$folderId]);if($n=$q->fetchColumn())return(string)$n;$q=$db->prepare("SELECT number FROM private_business_records WHERE folder_id=? ORDER BY kind DESC,created_at DESC LIMIT 1");$q->execute([$folderId]);if($n=$q->fetchColumn())return(string)$n;return pbNumber($db,'order','folder:'.$folderId,$year);}
function pbDefaults(string $profile): array {
    return ['customer_type'=>'consumer','company'=>'','first_name'=>'','last_name'=>'','billing_street'=>'','billing_postcode'=>'','billing_city'=>'','email'=>'','additional_email'=>'','phone'=>'','mobile'=>'','other_phone'=>'','contact'=>'','site_same'=>true,'site_street'=>'','site_postcode'=>'','site_city'=>'','scope'=>'','appointment'=>'','valid_until'=>'','pricing'=>'effort','flat_net'=>0,'hours'=>0,'hour_rate'=>220,'travel_rate'=>130,'km_rate'=>0.98,'incidental'=>40,'vat_rate'=>19,'origin'=>$profile==='marc'?'werdohl':'aalen','origin_street'=>'','origin_postcode'=>'','origin_city'=>'','oneway_km'=>0,'oneway_minutes'=>0,'visits'=>1,'route_source'=>'','notes'=>''];
}
function pbClean(array $in,string $profile): array {
    $d=pbDefaults($profile);foreach($d as $key=>$default){if(!array_key_exists($key,$in))continue;if(is_bool($default))$d[$key]=(bool)$in[$key];elseif(is_numeric($default)){if(!is_numeric($in[$key])||!is_finite((float)$in[$key])||(float)$in[$key]<0||(float)$in[$key]>1000000)throw new RuntimeException('Ungültiger Wert für '.$key.'.');$d[$key]=round((float)$in[$key],4);}else{$d[$key]=trim((string)$in[$key]);if(mb_strlen($d[$key])>($key==='scope'||$key==='notes'?12000:500))throw new RuntimeException('Eingabe zu lang: '.$key);}}
    if(!in_array($d['customer_type'],['consumer','business'],true)||!in_array($d['origin'],['aalen','werdohl','custom'],true)||!in_array($d['pricing'],['effort','flat'],true))throw new RuntimeException('Ungültige Auswahl.');
    foreach(['email','additional_email']as$key)if($d[$key]!==''&&!filter_var($d[$key],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Ungültige E-Mail-Adresse: '.$d[$key]);
    if($d['visits']<1||$d['visits']>100||floor((float)$d['visits'])!==(float)$d['visits'])throw new RuntimeException('Bitte eine ganze Zahl von 1 bis 100 Terminen eingeben.');
    if($d['vat_rate']>100)throw new RuntimeException('Ungültiger Umsatzsteuersatz.');
    return $d;
}
function pbCustomer(array $d): string {return trim($d['company'].' '.trim($d['first_name'].' '.$d['last_name']));}
function pbSite(array $d): array {return ['street'=>$d[$d['site_same']?'billing_street':'site_street'],'postcode'=>$d[$d['site_same']?'billing_postcode':'site_postcode'],'city'=>$d[$d['site_same']?'billing_city':'site_city']];}
function pbOrigin(array $d): array {return match($d['origin']){'aalen'=>['street'=>'Nordstraße 17','postcode'=>'73432','city'=>'Aalen'],'werdohl'=>['street'=>'Feldstraße 108','postcode'=>'58791','city'=>'Werdohl'],default=>['street'=>$d['origin_street'],'postcode'=>$d['origin_postcode'],'city'=>$d['origin_city']]};}
function pbTotals(array $d): array {
    $km=round($d['oneway_km']*2*$d['visits'],3);$hours=($d['oneway_minutes']*2*$d['visits'])/60;
    $lines=[['label'=>'Begutachtung / Analyse / Ausarbeitung','quantity'=>$d['hours'],'unit'=>'Std.','rate'=>$d['hour_rate'],'net'=>round($d['hours']*$d['hour_rate'],2)],['label'=>'Fahrtzeit - Hin- und Rückweg','quantity'=>$hours,'unit'=>'Std.','rate'=>$d['travel_rate'],'net'=>round($hours*$d['travel_rate'],2)],['label'=>'KFZ-Kosten - Hin- und Rückweg','quantity'=>$km,'unit'=>'km','rate'=>$d['km_rate'],'net'=>round($km*$d['km_rate'],2)],['label'=>'Nebenkostenpauschale','quantity'=>1,'unit'=>'pauschal','rate'=>$d['incidental'],'net'=>round($d['incidental'],2)]];
    $net=$d['pricing']==='flat'?round($d['flat_net'],2):round(array_sum(array_column($lines,'net')),2);$vat=round($net*$d['vat_rate']/100,2);
    return ['lines'=>$lines,'km_total'=>$km,'travel_hours'=>$hours,'net'=>$net,'vat'=>$vat,'gross'=>round($net+$vat,2)];
}
function pbMissing(array $d): array {$missing=[];foreach(['billing_street'=>'Rechnungsstraße','billing_postcode'=>'Rechnungs-PLZ','billing_city'=>'Rechnungsort','scope'=>'Leistungsbeschreibung']as$k=>$label)if($d[$k]==='')$missing[]=$label;if(pbCustomer($d)==='')$missing[]='Auftraggeber';foreach(pbSite($d)as$k=>$v)if($v==='')$missing[]='Terminadresse: '.$k;if($d['pricing']==='effort'&&$d['hours']<=0)$missing[]='Geschätzter Arbeitsumfang';if($d['pricing']==='flat'&&$d['flat_net']<=0)$missing[]='Pauschalhonorar';return $missing;}
function pbRecord(PDO $db,string $id,string $profile,bool $lock=false): array {$q=$db->prepare('SELECT * FROM private_business_records WHERE id=? AND profile=?'.($lock&&$db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''));$q->execute([$id,$profile]);$r=$q->fetch();if(!$r)throw new RuntimeException('Angebot oder Auftrag nicht gefunden oder nicht freigegeben.',403);$r['data']=json_decode($r['payload_json'],true,512,JSON_THROW_ON_ERROR);return $r;}
function pbEvent(PDO $db,string $id,string $event,array $detail=[]): void {$q=$db->prepare('INSERT INTO private_business_events(id,record_id,event,detail_json,created_at) VALUES(?,?,?,?,?)');$q->execute([pbUuid(),$id,$event,json_encode($detail,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),pbNow()]);}
function pbSave(PDO $db,string $profile,array $input): array {
    $data=pbClean((array)($input['data']??[]),$profile);$id=trim((string)($input['id']??''));$key=trim((string)($input['request_key']??''));if(!preg_match('/^[a-f0-9-]{36}$/i',$key))throw new RuntimeException('Speicherkennung fehlt. Bitte die Seite neu öffnen.');
    $db->beginTransaction();try{
        if($id===''){$q=$db->prepare('SELECT id FROM private_business_records WHERE request_key=? AND profile=?');$q->execute([$key,$profile]);$id=(string)($q->fetchColumn()?:'');if($id!==''){$r=pbRecord($db,$id,$profile);$db->commit();return$r;}}
        if($id===''){$id=pbUuid();$number=pbNumber($db,'offer','offer:'.$key);$q=$db->prepare('INSERT INTO private_business_records(id,profile,number,kind,parent_id,request_key,folder_id,payload_json,revision,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$id,$profile,$number,'offer',null,$key,null,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),1,'draft',pbNow(),pbNow()]);}
        else{$r=pbRecord($db,$id,$profile,true);if($r['status']==='converted')throw new RuntimeException('Dieses Angebot wurde bereits in einen Auftrag überführt. Bitte den Auftrag öffnen.',409);if((int)($input['revision']??0)!==(int)$r['revision'])throw new RuntimeException('Der Stand wurde zwischenzeitlich geändert. Bitte neu laden.',409);if(isset($r['data']['offer_number']))$data['offer_number']=$r['data']['offer_number'];$q=$db->prepare('UPDATE private_business_records SET payload_json=?,revision=revision+1,updated_at=? WHERE id=?');$q->execute([json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),pbNow(),$id]);}
        pbEvent($db,$id,'saved');$db->commit();return pbRecord($db,$id,$profile);
    }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw$e;}
}
function pbConvert(PDO $db,string $profile,string $id,bool $confirmed): array {
    if(!$confirmed)throw new RuntimeException('Bitte bestätigen, dass eine Beauftragung vorliegt.');$db->beginTransaction();try{$r=pbRecord($db,$id,$profile,true);if($r['kind']!=='offer'){$db->commit();return$r;}$q=$db->prepare("SELECT id FROM private_business_records WHERE parent_id=? AND kind='order'");$q->execute([$id]);if($found=$q->fetchColumn()){$db->commit();return pbRecord($db,(string)$found,$profile);}if(pbMissing($r['data']))throw new RuntimeException('Bitte zuerst die fehlenden Angebotsdaten ergänzen.');$newId=pbUuid();$number=pbNumber($db,'order','order:'.$id);$data=$r['data'];$data['offer_number']=$r['number'];$q=$db->prepare('INSERT INTO private_business_records(id,profile,number,kind,parent_id,request_key,folder_id,payload_json,revision,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$newId,$profile,$number,'order',$id,pbUuid(),$r['folder_id'],json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),1,'order',pbNow(),pbNow()]);$q=$db->prepare("UPDATE private_business_records SET status='converted',updated_at=? WHERE id=?");$q->execute([pbNow(),$id]);pbEvent($db,$newId,'converted',['offer_number'=>$r['number'],'beauftragung_bestaetigt'=>true]);$db->commit();return pbRecord($db,$newId,$profile);}catch(Throwable$e){if($db->inTransaction())$db->rollBack();throw$e;}
}
